int count_at_distance(int V, int g[][MAXV], int src, int k) {
    int level[MAXV];
    for (int i = 0; i < V; i++) level[i] = -1;
    level[src] = 0;
    int queue[MAXV];
    int qh = 0, qt = 0;
    queue[qt++] = src;
    while (qh < qt) {
        int u = queue[qh++];
        if (level[u] >= k) continue;
        for (int v = 0; v < V; v++) {
            if (g[u][v] && level[v] == -1) {
                level[v] = level[u] + 1;
                queue[qt++] = v;
            }
        }
    }
    int count = 0;
    for (int i = 0; i < V; i++) {
        if (level[i] == k) count++;
    }
    return count;
}

