#define MAXV 50

int largest_component(int V, int g[][MAXV]) {
    int visited[MAXV];
    for (int i = 0; i < V; i++) visited[i] = 0;
    int best = 0;
    for (int s = 0; s < V; s++) {
        if (visited[s]) continue;
        int queue[MAXV];
        int qh = 0, qt = 0;
        queue[qt++] = s;
        visited[s] = 1;
        int size = 0;
        while (qh < qt) {
            int u = queue[qh++];
            size++;
            for (int v = 0; v < V; v++) {
                if (g[u][v] && !visited[v]) {
                    visited[v] = 1;
                    queue[qt++] = v;
                }
            }
        }
        if (size > best) best = size;
    }
    return best;
}

int main(void) {
    int V, E;
    if (scanf("%d %d", &V, &E) != 2) return 0;
    int g[MAXV][MAXV];
