    int g[MAXV][MAXV];
    for (int i = 0; i < V; i++)
        for (int j = 0; j < V; j++) g[i][j] = 0;
    for (int e = 0; e < E; e++) {
        int u, v;
        scanf("%d %d", &u, &v);
        g[u][v] = 1;
        g[v][u] = 1;
    }
    int src;
    scanf("%d", &src);
    int parent[MAXV];
    bfs_parents(V, g, src, parent);
    print_arr(parent, V);
    return 0;
}
